package contracttest

// journeyStepsCatalog is the last part of the journey: batch updates and deletes, the library OPML export and multi-item download, quick match from a custom provider, and the metadata file removal. It ports replacement-trial.cjs journeySteps in order.
func journeyStepsCatalog(ids map[string]string) []journeyStep {
	return []journeyStep{
		{id: "batch.update.listener", who: "listener", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{"metadata": map[string]any{"title": "x"}}}}},
		{id: "batch.update.notarray", who: "root", method: "POST", route: "/api/items/batch/update", body: map[string]any{"id": ids["saga1"]}},
		{id: "batch.update.empty", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{}},
		{id: "batch.update.noid", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"mediaPayload": map[string]any{}}}},
		{id: "batch.update.dupid", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{}}, map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{}}}},
		{id: "batch.update.unknown", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{}}, map[string]any{"id": "00000000-0000-4000-8000-000000000000", "mediaPayload": map[string]any{}}}},
		{id: "batch.update.nochange", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{"metadata": map[string]any{}}}, map[string]any{"id": ids["saga2"], "mediaPayload": map[string]any{"tags": []any{}}}}},
		{id: "batch.update.apply", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{"metadata": map[string]any{"title": "Batch Title One", "subtitle": "Batch Sub", "genres": []any{"Batch"}, "explicit": true, "series": []any{map[string]any{"name": "Batch Series", "sequence": "7"}}}, "tags": []any{"batch-tag"}}}, map[string]any{"id": ids["saga2"], "mediaPayload": map[string]any{"metadata": map[string]any{"authors": []any{map[string]any{"name": "Batch Author"}}, "narrators": []any{"Batch Narrator"}, "publishedYear": 1999, "description": "<script>x</script><b>bold</b>"}}}}, events: 8},
		{id: "batch.update.after.saga1", who: "root", route: "/api/items/" + ids["saga1"] + "?expanded=1"},
		{id: "batch.update.after.saga2", who: "root", route: "/api/items/" + ids["saga2"] + "?expanded=1"},
		{id: "batch.update.after.authors", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "batch.update.after.series", who: "root", route: "/api/libraries/" + ids["library"] + "/series?limit=20&page=0&sort=name&desc=0&minified=1"},
		{id: "batch.update.after.filterdata", who: "root", route: "/api/libraries/" + ids["library"] + "?include=filterdata"},
		{id: "batch.update.revert", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["saga1"], "mediaPayload": map[string]any{"metadata": map[string]any{"series": []any{map[string]any{"name": "The Long Saga Renamed", "sequence": "1"}, map[string]any{"name": "Mega Cycle", "sequence": "1"}}}}}, map[string]any{"id": ids["saga2"], "mediaPayload": map[string]any{"metadata": map[string]any{"authors": []any{map[string]any{"name": "Terry Fixture"}}}}}}, events: 8},
		{id: "batch.update.after.authors2", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "batch.update.after.series2", who: "root", route: "/api/libraries/" + ids["library"] + "/series?limit=20&page=0&sort=name&desc=0&minified=1"},
		{id: "batch.update.podcast.badcron", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["podcast"], "mediaPayload": map[string]any{"autoDownloadSchedule": "nope", "metadata": map[string]any{"title": "Must Not Apply"}}}}},
		{id: "batch.update.podcast.ok", who: "root", method: "POST", route: "/api/items/batch/update", body: []any{map[string]any{"id": ids["podcast"], "mediaPayload": map[string]any{"metadata": map[string]any{"title": "Fixture Cast Batch", "author": "Batch Host"}, "tags": []any{"batch"}, "autoDownloadSchedule": "0 3 * * *"}}}, events: 3},
		{id: "batch.update.after.podcast", who: "root", route: "/api/items/" + ids["podcast"] + "?expanded=1"},
		{id: "batch.delete.listener", who: "listener", method: "POST", route: "/api/items/batch/delete", body: map[string]any{"libraryItemIds": []any{ids["ebook"]}}},
		{id: "batch.delete.noids", who: "root", method: "POST", route: "/api/items/batch/delete", body: map[string]any{}},
		{id: "batch.delete.notarray", who: "root", method: "POST", route: "/api/items/batch/delete", body: map[string]any{"libraryItemIds": "abc"}},
		{id: "batch.delete.empty", who: "root", method: "POST", route: "/api/items/batch/delete", body: map[string]any{"libraryItemIds": []any{}}},
		{id: "batch.delete.unknown", who: "root", method: "POST", route: "/api/items/batch/delete", body: map[string]any{"libraryItemIds": []any{"00000000-0000-4000-8000-000000000000"}}},
		{id: "batch.delete.soft", who: "root", method: "POST", route: "/api/items/batch/delete", body: map[string]any{"libraryItemIds": []any{ids["ebook"], "00000000-0000-4000-8000-000000000000"}}, events: 4},
		{id: "batch.delete.soft.again", who: "root", method: "POST", route: "/api/items/batch/delete", body: map[string]any{"libraryItemIds": []any{ids["ebook"]}}},
		{id: "batch.delete.after.items", who: "root", route: "/api/libraries/" + ids["library"] + "/items?limit=20&page=0&minified=1&sort=media.metadata.title"},
		{id: "batch.delete.after.item", who: "root", route: "/api/items/" + ids["ebook"]},
		{id: "batch.delete.after.series", who: "root", route: "/api/libraries/" + ids["library"] + "/series?limit=20&page=0&sort=name&desc=0&minified=1"},
		{id: "batch.delete.hard", who: "root", method: "POST", route: "/api/items/batch/delete?hard=1", body: map[string]any{"libraryItemIds": []any{ids["disposable"]}}, events: 4},
		{id: "batch.delete.after.authors", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "batch.delete.after.items2", who: "root", route: "/api/libraries/" + ids["library"] + "/items?limit=20&page=0&minified=1&sort=media.metadata.title"},
		{id: "opml.podcast.nofeed", who: "root", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml", binary: "xml"},
		{id: "opml.setup.feed", who: "root", method: "PATCH", route: "/api/items/" + ids["podcast"] + "/media", body: map[string]any{"metadata": map[string]any{"title": "Tom & \"Jerry\" <Show>", "feedUrl": "http://example.com/feed?a=1&b=2", "description": "Edited <b>podcast</b> & more", "itunesPageUrl": "https://podcasts.apple.com/podcast/id1", "language": "en-US"}}},
		{id: "opml.podcast", who: "root", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml", binary: "xml"},
		{id: "opml.podcast.listener", who: "listener", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml", binary: "xml"},
		{id: "opml.podcast.finisher", who: "finisher", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml", binary: "xml"},
		{id: "opml.book", who: "root", route: "/api/libraries/" + ids["library"] + "/opml", binary: "xml"},
		{id: "opml.limit.nan", who: "root", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml?limit=abc&page=", binary: "xml"},
		{id: "opml.limit.negative", who: "root", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml?limit=-1"},
		{id: "opml.page.fraction", who: "root", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml?page=1.5"},
		{id: "opml.missing", who: "root", route: "/api/libraries/00000000-0000-4000-8000-000000000000/opml"},
		{id: "opml.anon", route: "/api/libraries/" + ids["podcastLibrary"] + "/opml"},
		{id: "download.noids", who: "listener", route: "/api/libraries/" + ids["library"] + "/download"},
		{id: "download.emptyids", who: "listener", route: "/api/libraries/" + ids["library"] + "/download?ids="},
		{id: "download.unknown", who: "listener", route: "/api/libraries/" + ids["library"] + "/download?ids=00000000-0000-4000-8000-000000000000"},
		{id: "download.otherlibrary", who: "listener", route: "/api/libraries/" + ids["library"] + "/download?ids=" + ids["podcast"]},
		{id: "download.two", who: "listener", route: "/api/libraries/" + ids["library"] + "/download?ids=" + ids["saga1"] + "," + ids["saga2"], binary: "zip"},
		{id: "download.mixed", who: "listener", route: "/api/libraries/" + ids["library"] + "/download?ids=" + ids["novel"] + ",00000000-0000-4000-8000-000000000000," + ids["podcast"], binary: "zip"},
		{id: "download.root", who: "root", route: "/api/libraries/" + ids["library"] + "/download?ids=" + ids["saga2"], binary: "zip"},
		{id: "download.missinglibrary", who: "listener", route: "/api/libraries/00000000-0000-4000-8000-000000000000/download?ids=" + ids["saga1"]},
		{id: "match.provider.create", who: "root", method: "POST", route: "/api/custom-metadata-providers", bodyFn: func(c *journeyCtx) any {
			return map[string]any{"name": "Trial Provider", "url": c.fixtureURL + "/provider", "mediaType": "book"}
		}, capture: "matchProvider"},
		{id: "match.listener", who: "listener", method: "POST", route: "/api/items/" + ids["saga1"] + "/match", bodyFn: matchBody(nil)},
		{id: "match.missing", who: "root", method: "POST", route: "/api/items/00000000-0000-4000-8000-000000000000/match", bodyFn: matchBody(nil)},
		{id: "match.nomatch", who: "root", method: "POST", route: "/api/items/" + ids["saga1"] + "/match", bodyFn: matchBody(map[string]any{"title": "Nothing Here"})},
		{id: "match.saga2.plain", who: "root", method: "POST", route: "/api/items/" + ids["saga2"] + "/match", bodyFn: matchBody(nil), events: 8},
		{id: "match.saga1.override", who: "root", method: "POST", route: "/api/items/" + ids["saga1"] + "/match", bodyFn: matchBody(map[string]any{"overrideDetails": true, "overrideCover": true, "title": "Override Query", "author": "Terry Fixture"}), events: 8},
		{id: "match.saga1.again", who: "root", method: "POST", route: "/api/items/" + ids["saga1"] + "/match", bodyFn: matchBody(map[string]any{"overrideDetails": true}), events: 8},
		{id: "match.after.saga1", who: "root", route: "/api/items/" + ids["saga1"] + "?expanded=1"},
		{id: "match.after.saga2", who: "root", route: "/api/items/" + ids["saga2"] + "?expanded=1"},
		{id: "match.after.cover", who: "root", route: "/api/items/" + ids["saga1"] + "/cover?width=200&format=jpeg", binary: "bytes"},
		{id: "match.after.authors", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "match.after.series", who: "root", route: "/api/libraries/" + ids["library"] + "/series?limit=20&page=0&sort=name&desc=0&minified=1"},
		{id: "batchmatch.listener", who: "listener", method: "POST", route: "/api/items/batch/quickmatch", bodyFn: func(c *journeyCtx) any {
			return map[string]any{"libraryItemIds": []any{ids["novel"]}, "options": matchBody(nil)(c)}
		}},
		{id: "batchmatch.noids", who: "root", method: "POST", route: "/api/items/batch/quickmatch", body: map[string]any{}},
		{id: "batchmatch.unknown", who: "root", method: "POST", route: "/api/items/batch/quickmatch", body: map[string]any{"libraryItemIds": []any{"00000000-0000-4000-8000-000000000000"}}},
		{id: "batchmatch.run", who: "root", method: "POST", route: "/api/items/batch/quickmatch", bodyFn: func(c *journeyCtx) any {
			return map[string]any{"libraryItemIds": []any{ids["novel"], ids["saga2"], "00000000-0000-4000-8000-000000000000"}, "options": matchBody(map[string]any{"overrideDetails": true, "overrideCover": false})(c)}
		}, events: 12},
		{id: "batchmatch.after.novel", who: "root", route: "/api/items/" + ids["novel"] + "?expanded=1"},
		{id: "matchall.listener", who: "listener", route: "/api/libraries/" + ids["library"] + "/matchall"},
		{id: "matchall.missing", who: "root", route: "/api/libraries/00000000-0000-4000-8000-000000000000/matchall"},
		{id: "matchall.podcast", who: "root", route: "/api/libraries/" + ids["podcastLibrary"] + "/matchall"},
		{id: "matchall.setprovider", who: "root", method: "PATCH", route: "/api/libraries/" + ids["library"], bodyFn: matchBody(nil)},
		{id: "matchall.run", who: "root", route: "/api/libraries/" + ids["library"] + "/matchall", events: 14},
		{id: "matchall.after.items", who: "root", route: "/api/libraries/" + ids["library"] + "/items?limit=20&page=0&minified=1&sort=media.metadata.title"},
		{id: "search.podcast.noterm", who: "root", route: "/api/search/podcast"},
		{id: "search.podcast.array", who: "root", route: "/api/search/podcast?term=a&term=b"},
		{id: "search.podcast.country.array", who: "root", route: "/api/search/podcast?term=a&country=us&country=de"},
		{id: "search.podcast.long", who: "root", route: "/api/search/podcast?"},
		{id: "search.podcast.empty", who: "root", route: "/api/search/podcast?term="},
		{id: "search.podcast.anon", route: "/api/search/podcast?term=a"},
		{id: "metadata.remove.listener", who: "listener", method: "POST", route: "/api/libraries/" + ids["library"] + "/remove-metadata", body: map[string]any{}},
		{id: "metadata.remove.abs", who: "root", method: "POST", route: "/api/libraries/" + ids["library"] + "/remove-metadata?ext=abs", body: map[string]any{}},
		{id: "metadata.remove.json", who: "root", method: "POST", route: "/api/libraries/" + ids["library"] + "/remove-metadata", body: map[string]any{}},
		{id: "metadata.remove.again", who: "root", method: "POST", route: "/api/libraries/" + ids["library"] + "/remove-metadata?ext=json", body: map[string]any{}},
		{id: "metadata.remove.podcastlibrary", who: "root", method: "POST", route: "/api/libraries/" + ids["podcastLibrary"] + "/remove-metadata", body: map[string]any{}},
		{id: "metadata.remove.missing", who: "root", method: "POST", route: "/api/libraries/00000000-0000-4000-8000-000000000000/remove-metadata", body: map[string]any{}},
	}
}
